import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { lawsApi } from '../services/api';
import './LawsList.css';

const LawsList = () => {
  const [laws, setLaws] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionError, setConnectionError] = useState(false);

  useEffect(() => {
    const fetchLaws = async () => {
      try {
        setLoading(true);
        setConnectionError(false);
        const data = await lawsApi.getAllLaws();
        setLaws(data);
        setError(null);
      } catch (err) {
        console.error('Error fetching laws:', err);

        if (err.code === "ERR_NETWORK") {
          setConnectionError(true);
          setError('خطا در اتصال به سرور. لطفا از اجرای سرور بکند اطمینان حاصل کنید.');
        } else {
          setError('خطا در دریافت قوانین. لطفا دوباره تلاش کنید.');
        }
      } finally {
        setLoading(false);
      }
    };

    fetchLaws();
  }, []);

  if (loading) {
    return <div className="loading">در حال بارگذاری...</div>;
  }

  if (connectionError) {
    return (
      <div className="error-container">
        <div className="error">{error}</div>
        <div className="connection-help">
          <h3>راهنمای رفع مشکل:</h3>
          <ol>
            <li>اطمینان حاصل کنید که سرور بکند با دستور <code>npm run dev</code> در پوشه backend در حال اجراست.</li>
            <li>بررسی کنید که سرور بکند روی پورت 5001 در حال اجراست.</li>
            <li>مطمئن شوید که فایل .env در پوشه backend به درستی تنظیم شده است.</li>
            <li>بررسی کنید که اتصال به اینترنت برقرار است.</li>
          </ol>
          <button onClick={() => window.location.reload()} className="retry-btn">
            تلاش مجدد
          </button>
        </div>
      </div>
    );
  }

  if (error) {
    return <div className="error">{error}</div>;
  }

  if (laws.length === 0) {
    return (
      <div className="empty-state">
        <p>هیچ قانونی یافت نشد.</p>
        <Link to="/admin" className="btn">افزودن قانون جدید</Link>
      </div>
    );
  }

  return (
    <div className="laws-list">
      <h2>فهرست قوانین حقوقی</h2>
      <div className="laws-grid">
        {laws.map((law) => (
          <div className="law-card" key={law._id}>
            <h3>{law.title}</h3>
            <p className="law-category">دسته: {law.category}</p>
            <p className="law-description">{law.description.substring(0, 150)}...</p>
            <Link to={`/laws/${law._id}`} className="view-law">
              مشاهده جزئیات
            </Link>
          </div>
        ))}
      </div>
    </div>
  );
};

export default LawsList;
